import React, { useState } from 'react';
import './index.css'; // Import index.css for the new classes
interface LandingPageProps {
  onSelectView: (view: 'cli' | 'gui') => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSelectView }) => {
  const [bio] = useState<string>(
    "I am a Computer Science major at Strathmore University, deeply passionate about cybersecurity, distributed systems, software development, and AI/ML. Outside of academics, I'm an avid sportsman, actively involved in rugby and hitting the gym. My defining characteristic is grit; you could say it's my middle name."
  );

  return (
    <div className="landing-container" style={{ backgroundColor: '#1a1a1a', color: '#d9d9d9', fontFamily: "'Noto Sans', sans-serif", display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', padding: '20px', boxSizing: 'border-box' }}>
      {/* About Me Section */}
      <div style={{ textAlign: 'center', maxWidth: '800px', marginBottom: '40px' }}>
        <h2 className="large-text highlight" style={{ marginBottom: '10px', fontSize: '2em' }}>About Me</h2>
        <p className="info-text" style={{ lineHeight: '1.6', fontSize: '1.2em' }}>{bio}</p>
      </div>

      {/* Choice Section */}
      <div className="choice-container" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginBottom: '40px' }}>
        <div className="landing-box" onClick={() => onSelectView('cli')} style={{ width: '200px', height: '200px', border: '2px solid #007ACC', margin: '20px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
          <h1 className="bold-text" style={{ fontSize: '2.5em', margin: '0' }}>CLI</h1>
          <p className="small-text" style={{ fontSize: '1.2em', margin: '10px 0 0 0' }}>Launch Command Line Interface</p>
        </div>
        <div className="landing-box" onClick={() => onSelectView('gui')} style={{ width: '200px', height: '200px', border: '2px solid #007ACC', margin: '20px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
          <h1 className="bold-text" style={{ fontSize: '2.5em', margin: '0' }}>GUI</h1>
          <p className="small-text" style={{ fontSize: '1.2em', margin: '10px 0 0 0' }}>Explore Graphical User Interface</p>
        </div>
      </div>

      {/* Wakatime Section */}
      <div style={{ width: '100%', maxWidth: '1000px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '20px' }}>
        <img src="https://wakatime.com/share/@50b41ddf-bd05-4abf-9a01-63eeb1138150/cc39befd-e56e-4db1-ab5f-56922e06766b.svg" alt="Wakatime Languages Used" style={{ maxWidth: '50%', height: 'auto' }} />
        <img src="https://wakatime.com/share/@50b41ddf-bd05-4abf-9a01-63eeb1138150/dab37ba9-1c88-4d48-b7db-2e03771b4838.svg" alt="Wakatime Total Time Spent" style={{ maxWidth: '50%', height: 'auto' }} />
      </div>
    </div>
  );
};

export default LandingPage;
